export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const dt = 0.01;

  let initialized = false;
  // Estimated states for x, y, z
  let px = 0, py = 0, pz = 0;
  let vx = 0, vy = 0, vz = 0;
  let dx = 0, dy = 0, dz = 0; // disturbance accelerations

  // Inner loop & attitude disturbance estimation
  let simIntRoll = 0, simIntPitch = 0;
  let prevAction = { thrust: 0.45, roll: 0, pitch: 0, yawRate: 0 };
  let dobZRoll = 0, dobZPitch = 0, dobZYaw = 0;
  let attTrimRoll = 0, attTrimPitch = 0, yawTrim = 0;
  let filteredThrust = 0.45;
  let estKT = 20.0; // sum / (thrust * mass), nominal ~ 16 / 0.8 = 20

  // Navigation state
  let targetGate = -1;
  let phase = 'stage';
  let alignedCount = 0;

  return {
    step(obs) {
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;

      if (!initialized) {
        initialized = true;
        px = p.x; py = p.y; pz = p.z;
        vx = v.x; vy = v.y; vz = v.z;
        dobZRoll = -rates.roll / 0.06;
        dobZPitch = -rates.pitch / 0.06;
        dobZYaw = -rates.yaw / 0.08;
      } else {
        // 1. Update attitude inner-loop integral replica & DOB
        const tauAtt = 0.06;
        const errR = prevAction.roll - att.roll;
        const errP = prevAction.pitch - att.pitch;
        simIntRoll = clamp(simIntRoll + errR * dt, -0.35, 0.35);
        simIntPitch = clamp(simIntPitch + errP * dt, -0.35, 0.35);

        const uSimRoll = 65 * errR - 13.4 * rates.roll + 22 * simIntRoll;
        const uSimPitch = 65 * errP - 13.4 * rates.pitch + 22 * simIntPitch;
        const uSimYaw = 8 * (prevAction.yawRate - rates.yaw) - 0.4 * rates.yaw;

        dobZRoll += (-1 / tauAtt) * (dobZRoll + rates.roll / tauAtt + uSimRoll) * dt;
        dobZPitch += (-1 / tauAtt) * (dobZPitch + rates.pitch / tauAtt + uSimPitch) * dt;
        dobZYaw += (-1 / 0.08) * (dobZYaw + rates.yaw / 0.08 + uSimYaw) * dt;

        const distAccRoll = dobZRoll + rates.roll / tauAtt;
        const distAccPitch = dobZPitch + rates.pitch / tauAtt;
        const distAccYaw = dobZYaw + rates.yaw / 0.08;

        // Required action offset to cancel weak motor torque + inner integral
        attTrimRoll = clamp(-(distAccRoll + 22 * simIntRoll) / 65, -0.32, 0.32);
        attTrimPitch = clamp(-(distAccPitch + 22 * simIntPitch) / 65, -0.32, 0.32);
        yawTrim = clamp(-distAccYaw / 8, -0.8, 0.8);

        // 2. Translational prediction using actual measured attitude
        filteredThrust += (prevAction.thrust - filteredThrust) * (1 - Math.exp(-dt / 0.038));
        const bodyX = Math.sin(att.pitch) * Math.cos(att.roll);
        const bodyZ = -Math.sin(att.roll);
        const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
        const dirX = cy * bodyX + sy * bodyZ;
        const dirY = Math.cos(att.pitch) * Math.cos(att.roll);
        const dirZ = -sy * bodyX + cy * bodyZ;

        const estMass = clamp(16.0 / estKT, 0.6, 1.0);
        const dragCoeff = 0.42 / estMass;

        // Vertical thrust acceleration
        const aThrustTotal = estKT * filteredThrust;
        const ayKnown = aThrustTotal * dirY - dragCoeff * vy - 9.81;
        const axKnown = aThrustTotal * dirX - dragCoeff * vx;
        const azKnown = aThrustTotal * dirZ - dragCoeff * vz;

        // Predict pos & vel
        px += vx * dt + 0.5 * (axKnown + dx) * dt * dt;
        vx += (axKnown + dx) * dt;

        py += vy * dt + 0.5 * (ayKnown + dy) * dt * dt;
        vy += (ayKnown + dy) * dt;

        pz += vz * dt + 0.5 * (azKnown + dz) * dt * dt;
        vz += (azKnown + dz) * dt;

        // Correct with measurements
        const ex = p.x - px, evx = v.x - vx;
        px += 0.55 * ex;
        vx += 0.45 * evx + 8.0 * ex;
        if (p.y > 0.085) {
          dx = clamp(dx + (24.0 * evx + 60.0 * ex) * dt, -9.5, 9.5);
        }

        const ey = p.y - py, evy = v.y - vy;
        py += 0.55 * ey;
        vy += 0.45 * evy + 8.0 * ey;
        if (p.y > 0.085) {
          dy = clamp(dy + (14.0 * evy + 35.0 * ey) * dt, -5.0, 5.0);
          // Adapt estKT slowly so dy goes toward 0
          if (filteredThrust > 0.25 && dirY > 0.7) {
            estKT = clamp(estKT + 1.8 * dy * dt, 14.0, 26.5);
          }
        } else {
          dy = 0;
        }

        const ez = p.z - pz, evz = v.z - vz;
        pz += 0.55 * ez;
        vz += 0.45 * evz + 8.0 * ez;
        if (p.y > 0.085) {
          dz = clamp(dz + (24.0 * evz + 60.0 * ez) * dt, -9.5, 9.5);
        }
      }

      // 3. Navigation & Trajectory Planning
      let tx = px, ty = py, tz = pz;
      let tvx = 0, tvy = 0, tvz = 0;
      let kpX = 6.0, kdX = 4.2;
      let kpZ = 8.5, kdZ = 5.2;
      let kpY = 7.5, kdY = 4.5;

      if (obs.gateIndex < 3) {
        const g = obs.nextGate.centre;
        if (targetGate !== obs.gateIndex) {
          targetGate = obs.gateIndex;
          phase = 'stage';
          alignedCount = 0;
        }

        if (phase === 'stage') {
          // Stage in front of gate
          const stageDist = 0.28;
          tx = g.x - stageDist;
          ty = g.y;
          tz = g.z;

          // If we are accidentally past g.x (missed gate), first move safely in Z/Y outside frame or pull back
          if (px > g.x - 0.05) {
            // Pull back to stage
            tx = g.x - 0.35;
          }

          const errX = Math.abs(px - tx);
          const errY = Math.abs(py - g.y);
          const errZ = Math.abs(pz - g.z);
          if (errX < 0.14 && errY < 0.06 && errZ < 0.016 && Math.abs(vz) < 0.08 && Math.abs(vy) < 0.20 && vx > -0.15) {
            alignedCount++;
          } else {
            alignedCount = Math.max(0, alignedCount - 1);
          }
          if (alignedCount >= 6) {
            phase = 'cross';
          }
        }

        if (phase === 'cross') {
          // Drive decisively through the gate while keeping ultra-tight Z and Y lock
          tx = g.x + 0.35;
          ty = g.y;
          tz = g.z;
          tvx = 0.9;
          kpX = 5.5; kdX = 3.8;
          kpZ = 11.0; kdZ = 6.0;
          kpY = 8.5; kdY = 4.8;

          // Abort cross back to stage if knocked off Z before crossing plane
          const distToGateX = g.x - px;
          const predZAtGate = distToGateX > 0 ? pz + vz * clamp(distToGateX / Math.max(0.3, vx), 0, 0.25) : pz;
          if (distToGateX > 0.05 && (Math.abs(pz - g.z) > 0.025 || Math.abs(predZAtGate - g.z) > 0.027 || Math.abs(py - g.y) > 0.10)) {
            phase = 'stage';
            alignedCount = 0;
            tx = g.x - 0.28;
            tvx = 0;
          }
        }
      } else {
        // All 3 gates passed: fly to landing pad (2.05, 0, 1.65)
        const pad = obs.pad.centre;
        if (phase !== 'land_descend' && phase !== 'land_touchdown') {
          phase = 'land_approach';
        }
        const horizDist = Math.hypot(px - pad.x, pz - pad.z);
        const horizSpeed = Math.hypot(vx, vz);

        tx = pad.x;
        tz = pad.z;

        if (phase === 'land_approach') {
          // Descend smoothly as we get closer to the pad
          ty = clamp(0.18 + 0.55 * horizDist, 0.18, 0.85);
          if (horizDist < 0.11 && horizSpeed < 0.25 && py < 0.30) {
            phase = 'land_descend';
          }
        }
        if (phase === 'land_descend') {
          ty = 0.07;
          tvy = -0.15;
          if (horizDist > 0.14) {
            phase = 'land_approach';
          } else if (py <= 0.092 && Math.abs(vy) < 0.25) {
            phase = 'land_touchdown';
          }
        }
        if (phase === 'land_touchdown') {
          ty = 0.05;
          tvy = 0;
          if (horizDist > 0.14) {
            phase = 'land_approach';
          }
        }
      }

      // 4. Compute desired world accelerations (including drag & disturbance cancellation)
      const estMass = clamp(16.0 / estKT, 0.6, 1.0);
      const dragCoeff = 0.42 / estMass;

      const desAx = clamp(kpX * (tx - px) + kdX * (tvx - vx) - dx + dragCoeff * vx, -5.5, 5.5);
      const desAz = clamp(kpZ * (tz - pz) + kdZ * (tvz - vz) - dz + dragCoeff * vz, -5.5, 5.5);
      const desAy = clamp(kpY * (ty - py) + kdY * (tvy - vy) - dy + dragCoeff * vy, -4.5, 5.5);

      const totalAy = Math.max(2.5, 9.81 + desAy);

      // Convert desired world (desAx, totalAy, desAz) into desired roll & pitch
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const bodyAx = cy * desAx - sy * desAz;
      const bodyAz = sy * desAx + cy * desAz;

      const desPitch = clamp(Math.atan2(bodyAx, totalAy), -0.52, 0.52);
      const desRoll = clamp(Math.atan2(-bodyAz, Math.hypot(bodyAx, totalAy)), -0.52, 0.52);

      // Lead compensation + weak-motor trim for inner attitude loop
      let cmdPitch = clamp(desPitch + attTrimPitch + 0.35 * (desPitch - att.pitch) - 0.04 * rates.pitch, -0.6, 0.6);
      let cmdRoll = clamp(desRoll + attTrimRoll + 0.35 * (desRoll - att.roll) - 0.04 * rates.roll, -0.6, 0.6);

      const cosTilt = Math.max(0.55, Math.cos(att.roll) * Math.cos(att.pitch));
      let cmdThrust = clamp(totalAy / (estKT * cosTilt), 0.05, 1.0);

      if (phase === 'land_touchdown' && py <= 0.088 && Math.hypot(px - obs.pad.centre.x, pz - obs.pad.centre.z) < 0.12 && Math.hypot(vx, vz) < 0.25) {
        // Settle softly on pad with minimal tilt
        cmdThrust = 0.05;
        cmdRoll = clamp(attTrimRoll * 0.2, -0.10, 0.10);
        cmdPitch = clamp(attTrimPitch * 0.2, -0.10, 0.10);
      }

      const cmdYawRate = clamp(yawTrim - 2.5 * att.yaw - 0.2 * rates.yaw, -2, 2);

      prevAction = { thrust: cmdThrust, roll: cmdRoll, pitch: cmdPitch, yawRate: cmdYawRate };
      return prevAction;
    },
  };
}

