  let initialized = false;
  let px = 0, py = 0, pz = 0;
  let vx = 0, vy = 0, vz = 0;
  let prevVx = 0, prevVy = 0, prevVz = 0;
  let prevAxKnown = 0, prevAyKnown = 0, prevAzKnown = 0;
  let dx = 0, dy = 0, dz = 0; // fast wind/disturbance acceleration estimates

  // Attitude tracking & weak-motor trim
  let desRollLagged = 0, desPitchLagged = 0;
  let trimRoll = 0, trimPitch = 0, trimYaw = 0;
  let prevAction = { thrust: 0.45, roll: 0, pitch: 0, yawRate: 0 };
  let filteredThrust = 0.45;
  let estKT = 20.0;

  // Navigation state
  let targetGate = -1;
  let phase = 'stage';
  let alignedCount = 0;

  return {
    step(obs) {
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;

      if (!initialized) {
        initialized = true;
        px = p.x; py = p.y; pz = p.z;
        vx = v.x; vy = v.y; vz = v.z;
        prevVx = vx; prevVy = vy; prevVz = vz;
      } else {
        // 1. Update filtered thrust and known model accelerations from actual measured attitude
        filteredThrust += (prevAction.thrust - filteredThrust) * (1 - Math.exp(-dt / 0.038));

        const bodyX = Math.sin(att.pitch) * Math.cos(att.roll);
        const bodyZ = -Math.sin(att.roll);
        const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
        const dirX = cy * bodyX + sy * bodyZ;
        const dirY = Math.cos(att.pitch) * Math.cos(att.roll);
        const dirZ = -sy * bodyX + cy * bodyZ;

        const estMass = clamp(16.0 / estKT, 0.6, 1.0);
        const dragCoeff = 0.42 / estMass;

        // Predict pos & vel using previous step's known accel + disturbance
        px += vx * dt + 0.5 * (prevAxKnown + dx) * dt * dt;
        vx += (prevAxKnown + dx) * dt;
        py += vy * dt + 0.5 * (prevAyKnown + dy) * dt * dt;
        vy += (prevAyKnown + dy) * dt;
        pz += vz * dt + 0.5 * (prevAzKnown + dz) * dt * dt;
        vz += (prevAzKnown + dz) * dt;

        // Kinematic measurement update
        const ex = p.x - px, evx = v.x - vx;
        px += 0.65 * ex;
        vx += 0.55 * evx + 10.0 * ex;

        const ey = p.y - py, evy = v.y - vy;
        py += 0.65 * ey;
        vy += 0.55 * evy + 10.0 * ey;

        const ez = p.z - pz, evz = v.z - vz;
        pz += 0.65 * ez;
        vz += 0.55 * evz + 10.0 * ez;

