          const instAx = (vx - prevVx) / dt;
          const instAz = (vz - prevVz) / dt;
          dx = clamp((1 - alphaW) * dx + alphaW * (instAx - prevAxKnown), -10.0, 10.0);
          dz = clamp((1 - alphaW) * dz + alphaW * (instAz - prevAzKnown), -10.0, 10.0);

          const alphaY = dt / (0.08 + dt);
          const instAy = (vy - prevVy) / dt;
          dy = clamp((1 - alphaY) * dy + alphaY * (instAy - prevAyKnown), -5.0, 5.0);

