        const aThrustTotal = estKT * filteredThrust;
        prevAyKnown = aThrustTotal * dirY - dragCoeff * vy - 9.81;
        prevAxKnown = aThrustTotal * dirX - dragCoeff * vx;
        prevAzKnown = aThrustTotal * dirZ - dragCoeff * vz;
