      let tvx = 0, tvy = 0, tvz = 0;
      let kpX = 6.2, kdX = 4.2;
      let kpZ = 9.5, kdZ = 5.5;
      let kpY = 8.0, kdY = 4.6;

      if (obs.gateIndex < 3) {
